def factor_small(n, primes):
    # trial division using primes list; return prime factors (unique)
    res = []
    tmp = n
    for p in primes:
        if p*p > tmp:
            break
        if tmp % p == 0:
            res.append(p)
            while tmp % p == 0:
                tmp //= p
    if tmp > 1:
        res.append(tmp)
    return res

